<?php
$titulo='Gastos';require_once 'header.php';procesarGastosRecurrentes($conn);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  validarCsrf();$id=(int)($_POST['id']??0);$tipo=$_POST['tipo']??'otro';$concepto=trim($_POST['concepto']??'');$monto=(float)($_POST['monto']??0);$freq=$_POST['frecuencia']??'unico';$fecha=$_POST['fecha_inicio']??date('Y-m-d');$prox=$freq==='unico'?null:($_POST['proxima_fecha']?:$fecha);$productoId=(int)($_POST['producto_id']??0);$cantidadInv=(float)($_POST['cantidad_inventario']??0);
  if($concepto==='')throw new RuntimeException('El concepto es obligatorio.');if($monto<=0)throw new RuntimeException('El monto debe ser mayor que cero.');
  if($id){
   $st=$conn->prepare("UPDATE gastos SET tipo=?,concepto=?,monto=?,frecuencia=?,fecha_inicio=?,proxima_fecha=? WHERE id=?");$st->bind_param('ssdsssi',$tipo,$concepto,$monto,$freq,$fecha,$prox,$id);$st->execute();registrarHistorial($conn,'gastos','editar','Gasto actualizado',['gasto'=>$id,'concepto'=>$concepto,'monto'=>$monto,'tipo'=>$tipo]);flash('success','Gasto actualizado.');
  }else{
   $uid=(int)($_SESSION['usuario']['id']??0);$caja=cajaAbierta($conn);$cajaId=$caja?(int)$caja['id']:null;
   $conn->begin_transaction();
   if($tipo==='inventario'){
    if($productoId<=0)throw new RuntimeException('Selecciona el producto que ingresó al inventario.');if($cantidadInv<=0)throw new RuntimeException('Indica una cantidad de inventario mayor que cero.');
    $st=$conn->prepare("SELECT nombre,stock FROM productos WHERE id=? AND activo=1 FOR UPDATE");$st->bind_param('i',$productoId);$st->execute();$prod=$st->get_result()->fetch_assoc();if(!$prod)throw new RuntimeException('El producto no existe o está inactivo.');
    $stockAnterior=(float)$prod['stock'];$stockNuevo=$stockAnterior+$cantidadInv;
    $st=$conn->prepare("UPDATE productos SET stock=? WHERE id=?");$st->bind_param('di',$stockNuevo,$productoId);$st->execute();
    $st=$conn->prepare("INSERT INTO gastos(usuario_id,tipo,concepto,monto,frecuencia,fecha_inicio,proxima_fecha,estado,producto_id,cantidad_inventario,caja_id) VALUES(?,?,?,?,?,?,?,'pagado',?,?,?)");$st->bind_param('issdsssidi',$uid,$tipo,$concepto,$monto,$freq,$fecha,$prox,$productoId,$cantidadInv,$cajaId);$st->execute();$gid=$st->insert_id;
    $origen='compra';$movTipo='entrada';$motivo='Compra inventario - Gasto #'.$gid;$obs='Entrada automática desde gastos';$st=$conn->prepare("INSERT INTO movimientos_inventario(producto_id,usuario_id,tipo,origen,cantidad,stock_anterior,stock_nuevo,motivo,observacion) VALUES(?,?,?,?,?,?,?,?,?)");$st->bind_param('iissdddss',$productoId,$uid,$movTipo,$origen,$cantidadInv,$stockAnterior,$stockNuevo,$motivo,$obs);$st->execute();
    $st=$conn->prepare("INSERT INTO movimientos_caja(usuario_id,caja_id,gasto_id,tipo,monto,concepto) VALUES(?,?,?,'salida',?,?)");$cc='Compra inventario: '.$concepto;$st->bind_param('iiids',$uid,$cajaId,$gid,$monto,$cc);$st->execute();
   }else{
    $st=$conn->prepare("INSERT INTO gastos(usuario_id,tipo,concepto,monto,frecuencia,fecha_inicio,proxima_fecha,estado,caja_id) VALUES(?,?,?,?,?,?,?,'activo',?)");$st->bind_param('issdsssi',$uid,$tipo,$concepto,$monto,$freq,$fecha,$prox,$cajaId);$st->execute();$gid=$st->insert_id;
    if($freq==='unico'){$st=$conn->prepare("UPDATE gastos SET estado='pagado' WHERE id=?");$st->bind_param('i',$gid);$st->execute();$st=$conn->prepare("INSERT INTO movimientos_caja(usuario_id,caja_id,gasto_id,tipo,monto,concepto) VALUES(?,?,?,'salida',?,?)");$cc='Gasto: '.$concepto;$st->bind_param('iiids',$uid,$cajaId,$gid,$monto,$cc);$st->execute();}
   }
   $conn->commit();registrarHistorial($conn,'gastos','crear',$tipo==='inventario'?'Gasto de inventario creado y stock aumentado':'Gasto creado',['gasto'=>$gid,'tipo'=>$tipo,'concepto'=>$concepto,'monto'=>$monto,'producto'=>$productoId,'cantidad_inventario'=>$cantidadInv]);flash('success',$tipo==='inventario'?'Gasto guardado y stock aumentado automáticamente.':'Gasto guardado.');
  }
 }catch(Throwable $e){if($conn->in_transaction)$conn->rollback();flash('error',$e->getMessage());}
 redir('gastos.php');
}
$total=$conn->query("SELECT COALESCE(SUM(monto),0) v FROM gastos WHERE MONTH(fecha_inicio)=MONTH(CURDATE()) AND YEAR(fecha_inicio)=YEAR(CURDATE())")->fetch_assoc()['v'];$gs=$conn->query("SELECT g.*,p.nombre producto FROM gastos g LEFT JOIN productos p ON p.id=g.producto_id ORDER BY g.id DESC");$prods=$conn->query("SELECT id,nombre,stock,unidad FROM productos WHERE activo=1 ORDER BY nombre");
?>
<div class="toolbar"><div><h2>Gastos</h2><p>Registra gastos. Si el tipo es Inventario, selecciona el producto y la cantidad: el stock aumenta automáticamente.</p></div></div><div class="stat single"><small>Gastos del mes</small><b><?=dinero((float)$total)?></b></div>
<section class="panel"><h2>Registrar gasto</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="0"><label>Tipo<select name="tipo" id="tipoGasto"><option value="fijo">Fijo</option><option value="imprevisto">Imprevisto</option><option value="inventario">Inventario / compra</option><option value="otro">Otro</option></select></label><label>Concepto<input name="concepto" required placeholder="Ej. compra de cerveza"></label><label>Monto total<input type="number" step="0.01" min=".01" name="monto" required></label><div id="bloqueInventario" class="span-2" style="display:none"><div class="form-grid"><label>Producto comprado<select name="producto_id"><option value="0">Seleccionar producto</option><?php while($p=$prods->fetch_assoc()):?><option value="<?=$p['id']?>"><?=e($p['nombre'])?> — stock actual <?=e($p['stock'])?> <?=e($p['unidad'])?></option><?php endwhile;?></select></label><label>Cantidad que ingresó<input type="number" step="0.01" min=".01" name="cantidad_inventario" value="1"></label></div></div><label>Frecuencia<select name="frecuencia"><option value="unico">Una vez</option><option value="diario">Diario</option><option value="semanal">Semanal</option><option value="quincenal">Quincenal</option><option value="mensual">Mensual</option></select></label><label>Fecha<input type="date" name="fecha_inicio" value="<?=date('Y-m-d')?>" required></label><label>Próxima fecha<input type="date" name="proxima_fecha" value="<?=date('Y-m-d')?>"></label><button class="btn primary">Guardar gasto</button></form></section>
<section class="panel table-wrap"><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Tipo</th><th>Producto</th><th>Cantidad</th><th>Monto</th><th>Estado</th></tr></thead><tbody><?php while($g=$gs->fetch_assoc()):?><tr><td><?=e($g['fecha_inicio'])?></td><td><?=e($g['concepto'])?></td><td><?=e($g['tipo'])?></td><td><?=e($g['producto']??'—')?></td><td><?=isset($g['cantidad_inventario'])&&$g['cantidad_inventario']!==null?e($g['cantidad_inventario']):'—'?></td><td><?=dinero((float)$g['monto'])?></td><td><?=e($g['estado'])?></td></tr><?php endwhile;?></tbody></table></section>
<script>const tg=document.getElementById('tipoGasto'),bi=document.getElementById('bloqueInventario');function inv(){bi.style.display=tg.value==='inventario'?'block':'none'}tg.addEventListener('change',inv);inv();</script>
